```python
import datetime


def parse_rows(text):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    names = lines[0].split("\t")
    rows = []
    for ln in lines[1:]:
        row = {}
        for name, raw in zip(names, ln.split("\t")):
            raw = raw.strip()
            if name in ("accession", "variety"):
                row[name] = raw
            elif name == "harvested":
                row[name] = datetime.date.fromisoformat(raw)
            else:
                try:
                    row[name] = int(raw)
                except ValueError:
                    try:
                        row[name] = float(raw)
                    except ValueError:
                        row[name] = raw
        rows.append(row)
    return rows
